SELECT a.APPLICATION_ID, a.APPLICATION_NO, r.REQUIREMENT_ID, r.DOCUMENT_TYPE_CODE, dt.NAME_AR DOCUMENT_NAME_AR, r.PARTY_ROLE_CODE, r.EMPLOYMENT_TYPE_CODE, r.NOTES_AR FROM MFF_APPLICATIONS a JOIN MFF_PROGRAM_DOC_REQUIREMENTS r ON r.PROGRAM_VERSION_ID = a.PROGRAM_VERSION_ID AND r.REQUIRED_FLAG = 'Y' AND TRUNC(SYSDATE) BETWEEN NVL(r.EFFECTIVE_FROM,DATE '1900-01-01') AND NVL(r.EFFECTIVE_TO,DATE '2999-12-31') JOIN REF_MFF_DOCUMENT_TYPE dt ON dt.CODE = r.DOCUMENT_TYPE_CODE JOIN MFF_PERSONS pp ON pp.PERSON_ID = a.PRIMARY_PERSON_ID WHERE (r.EMPLOYMENT_TYPE_CODE IS NULL OR r.EMPLOYMENT_TYPE_CODE = pp.EMPLOYMENT_TYPE_CODE) AND NOT EXISTS ( SELECT 1 FROM MFF_APPLICATION_DOCUMENTS d WHERE d.APPLICATION_ID = a.APPLICATION_ID AND d.DOCUMENT_TYPE_CODE = r.DOCUMENT_TYPE_CODE AND NVL(d.VERIFICATION_STATUS,'RECEIVED') IN ('RECEIVED','VERIFIED','ACCEPTED') );
